:root{
  --v-brand:var(--blue-800); --v-brand-hover:var(--blue-800); --v-link:var(--blue-800);
  --v-ink:var(--slate-900); --v-ink-2:var(--blue-800); --v-muted:var(--slate-600); --v-muted-2:var(--slate-500); --v-muted-3:var(--slate-400);
  --v-line:var(--slate-200); --v-line-soft:var(--slate-100); --v-line-2:var(--slate-300);
  --v-head:var(--blue-50); --v-hover:var(--blue-50); --v-select:var(--blue-50); --v-band:var(--blue-50);
  --v-track:var(--blue-100); --v-fill:var(--blue-800);
  --v-ok:var(--green-600); --v-ok-ink:var(--green-800); --v-ok-bg:var(--green-100); --v-ok-line:var(--green-200);
  --v-warn:var(--amber-600); --v-warn-ink:var(--orange-800); --v-warn-bg:var(--amber-100); --v-warn-line:var(--amber-200);
  --v-bad:var(--red-600); --v-bad-ink:var(--red-800); --v-bad-bg:var(--red-100); --v-bad-line:var(--red-200);
  --v-info-ink:var(--blue-800); --v-info-bg:var(--blue-100); --v-info-line:var(--blue-200);
  --v-grey-dot:var(--slate-400);
  --v-r-card:12px; --v-r-ctl:8px; --v-r-pill:999px;
}
body{background:var(--slate-100)}
.ds-card,.ds-ov-stat,.ds-cc,.ds-dh-card{background:#fff;border:1px solid var(--v-line);border-radius:var(--v-r-card);box-shadow:none}
