.ds-btn--primary{background:var(--v-brand);border-color:var(--v-brand);color:#fff}
.ds-btn--primary:hover{background:var(--v-brand-hover);border-color:var(--v-brand-hover)}
.ds-btn--outline{background:#fff;border:1px solid var(--v-line-2);color:var(--v-ink-2)}
