.ds-badge{height:1.25rem;padding:0 .5rem;border-radius:var(--v-r-pill);font-size:12px;font-weight:500;line-height:1;display:inline-flex;align-items:center;background:var(--slate-100);color:var(--v-ink-2);border:0;white-space:nowrap}
.ds-badge--success{background:var(--v-ok-bg);color:var(--v-ok-ink)}
.ds-badge--warn{background:var(--v-warn-bg);color:var(--v-warn-ink)}
.ds-badge--danger{background:var(--v-bad-bg);color:var(--v-bad-ink)}
.ds-badge--info{background:var(--v-info-bg);color:var(--v-info-ink)}
