.req-flash{outline:3px solid var(--blue-600);outline-offset:4px;border-radius:12px;box-shadow:var(--shadow-xs);transition:outline-color .3s,box-shadow .3s}
.cq-drawer .ds-drawer-head>div:first-child h2{display:flex;align-items:center;gap:10px}
.cq-hav{width:36px;height:36px;font-size:13px;flex:none}
.cq-kpis{grid-template-columns:repeat(5,minmax(0,1fr))}
.cq-kpi{padding:10px 12px}
.cq-kpi b{font-size:16px}
.cq-scope{align-self:flex-start}
.cq-vp{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:10px 0;border-bottom:1px solid var(--slate-100)}
.cq-vp>div:first-child{min-width:0;display:flex;flex-direction:column;gap:2px}
.cq-vp>div:first-child b{font-size:14px;font-weight:600;color:var(--slate-900)}
.cq-vp>div:first-child span{font-size:12px;color:var(--slate-500)}
.cq-vp-r{display:flex;align-items:center;gap:10px;flex:none}
.cq-vp-r b{font-size:14px;font-variant-numeric:tabular-nums}
.cq-var{font-size:12px;font-weight:600;border-radius:16px;padding:2px 8px;font-variant-numeric:tabular-nums}
.cq-var.is-up{background:var(--green-50);color:var(--green-800)}
.cq-var.is-down{background:var(--red-50);color:var(--red-700)}
.cq-jc{border:1px solid var(--slate-200);border-radius:12px;padding:14px;background:#fff;margin-bottom:10px}
.cq-jc.is-current{border-color:var(--blue-200)}
.cq-jc-h{display:flex;justify-content:space-between;align-items:flex-start;gap:10px}
.cq-jc-h b{display:block;font-size:14px;color:var(--slate-900)}
.cq-jc-h span{font-size:12px;color:var(--slate-500)}
.cq-live{font-size:12px;font-weight:600;background:var(--blue-50);color:var(--blue-800);border-radius:16px;padding:4px 10px;white-space:nowrap}
.cq-jc-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));margin-top:12px;border:1px solid var(--slate-100);border-radius:8px}
.cq-jc-stats>div{padding:8px 10px;border-left:1px solid var(--slate-100)}
.cq-jc-stats>div:first-child{border-left:0}
.cq-jc-stats span{display:block;font-size:12px;color:var(--slate-500)}
.cq-jc-stats b{display:block;font-size:14px;font-variant-numeric:tabular-nums}
.cq-jc-stats small{font-size:12px;color:var(--slate-500)}
.cq-inst{margin-top:10px;display:flex;flex-direction:column}
.cq-inst-r{display:grid;grid-template-columns:70px minmax(0,1fr) auto auto;gap:10px;align-items:center;font-size:13px;padding:6px 0;border-top:1px solid var(--slate-100)}
.cq-inst-r span:nth-child(2){min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.cq-inst-r em{font-style:normal;font-size:12px;color:var(--blue-800);background:var(--blue-50);border-radius:6px;padding:0 6px;margin-left:4px}
.cq-inst-r b{font-variant-numeric:tabular-nums}
.cq-inst-r>span:last-child{color:var(--slate-500);font-variant-numeric:tabular-nums}
.cq-jc.is-min{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:10px 14px}
.cq-jc.is-min>div:first-child{min-width:0}
.cq-jc.is-min b{display:block;font-size:13px;color:var(--slate-900);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cq-jc.is-min span{font-size:12px;color:var(--slate-500)}
.cq-jc-mini{display:flex;flex-direction:column;align-items:flex-end;gap:2px;flex:none;font-variant-numeric:tabular-nums}
.cq-stats{gap:8px;border:0;overflow:visible}
.cq-stats>div{border:1px solid var(--slate-200);border-radius:8px;padding:12px 14px}
.cq-stats>div:first-child{border-left:1px solid var(--slate-200)}
.cq-kpis{gap:8px;border:0;overflow:visible}
.cq-kpi{border:1px solid var(--slate-200);border-radius:8px}
.cq-pc{display:flex;justify-content:space-between;align-items:center;gap:14px;border:1px solid var(--slate-200);border-radius:12px;padding:12px;background:#fff}
.cq-pc-main{min-width:0;flex:1}
.cq-pc-side{display:flex;flex-direction:column;align-items:flex-end;gap:4px;flex:none;text-align:right}
.cq-pc-v{font-size:13px;color:var(--slate-500);display:inline-flex;gap:6px;align-items:center}
.cq-pc-v b{color:var(--slate-900);font-size:14px;font-variant-numeric:tabular-nums}
.cq-pc-m{font-size:12px;color:var(--slate-500);display:inline-flex;gap:6px;align-items:center;font-variant-numeric:tabular-nums}
.cq-camp-cards{grid-template-columns:1fr}
.cq-drawer .campl-card{border:1px solid var(--slate-200)}
.cq-sec:has(.cq-pc){gap:10px}
.cq-pc{padding:10px 12px;gap:12px;border:0;border-radius:12px;background:#fff;box-shadow:var(--shadow-md);transition:box-shadow .15s ease}
.cq-pc:hover{box-shadow:var(--shadow-md)}
.cq-pc .cq-pc-main .pl-cell{gap:10px}
.cq-pc .pl-thumb{width:40px;height:40px;border-radius:8px;font-size:12px;padding-bottom:4px}
.cq-pc .pl-txt strong{font-size:13px}
.cq-pc .pl-txt a{font-size:12px;max-width:200px}
.cq-pc .pl-go{width:30px;height:30px;border-radius:8px}
.cq-pc .pl-go svg{width:13px;height:13px}
.cq-pc-side{gap:4px}
.cq-pc-v{font-size:12px;gap:6px}
.cq-pc-v b{font-size:13px}
.cq-pc-m{font-size:12px}
.cq-pc .cq-var{font-size:12px;padding:1px 8px}
.cq-pc .cq-pc-main .pl-cell{width:100%}
.cq-pc .pl-txt{flex:1 1 auto;min-width:0}
.cq-pc .pl-go{margin-left:auto}
.cq-pc .cq-pc-side{width:168px;align-items:flex-end}
.cq-pc .cq-pc-m{white-space:nowrap}
.cq-th{width:26px;height:26px;border-radius:6px;display:inline-flex;align-items:flex-end;justify-content:center;padding-bottom:4px;color:#fff;text-decoration:none;flex:none}
.cq-th b{font-size:12px;font-weight:600;letter-spacing:.02em;line-height:1}
.cq-th:hover{outline:2px solid color-mix(in srgb, var(--blue-800) 35%, transparent);outline-offset:1px}
.cq-strip{display:flex;flex-wrap:wrap;gap:6px;margin-top:10px}
.cq-inst-r{grid-template-columns:26px minmax(0,1fr) auto auto auto;gap:10px}
.cq-inst-t{min-width:0;display:flex;flex-direction:column}
.cq-inst-t b{font-size:12px;font-weight:600;color:var(--slate-900);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cq-inst-t span{font-size:12px;color:var(--slate-500)}
.cq-inst-n{font-size:12px;color:var(--slate-500);font-variant-numeric:tabular-nums;white-space:nowrap}
.cs-ev-body .cq-jc{margin-bottom:0;width:100%;box-shadow:var(--shadow-md);border:0}
.cs-ev-body .cq-jc.is-min{display:block;padding:12px 14px}
.cq-layout--solo{grid-template-columns:1fr}
.cq-spoc{display:flex;flex-direction:column;gap:6px;max-width:320px}
.cq-spoc span{font-size:12px;color:var(--slate-500);font-weight:600;text-transform:uppercase;letter-spacing:.04em}
.cq-notes-box{width:100%;border:1px solid var(--blue-200);border-radius:12px;padding:12px 14px;font-size:14px;resize:vertical;min-height:160px;background:#fff;box-shadow:var(--shadow-xs)}
.cq-notes-box:focus{outline:2px solid color-mix(in srgb, var(--blue-800) 25%, transparent);border-color:var(--blue-800)}
.cq-sec .cq-notes-box{margin-top:4px}
.cq-th{width:38px;height:38px;border-radius:8px;padding-bottom:4px}
.cq-th b{font-size:12px;font-weight:600;letter-spacing:0;line-height:1}
.cq-strip{gap:6px}
.cq-inst-r{grid-template-columns:38px minmax(0,1fr) auto auto auto}
.cq-more{margin-top:6px}
.cq-more>summary{list-style:none;cursor:pointer;display:inline-flex;align-items:center;gap:6px;font-size:12px;font-weight:600;color:var(--slate-900);padding:8px 12px;border:1px solid var(--blue-200);border-radius:16px;background:#fff}
.cq-more>summary::-webkit-details-marker{display:none}
.cq-more>summary:hover{background:var(--blue-50)}
.cq-more[open]>summary{margin-bottom:4px}
.cq-inst--rest{margin-top:0}
.cq-tabs{position:sticky;top:0;z-index:20;background:#fff;margin:20px -28px 0;padding:6px 28px 0;border-bottom:1px solid var(--slate-200)}
.cq-tabs button{margin-bottom:-1px}
.my-tools{position:sticky;top:0;z-index:30;background:#fff;margin:16px -32px 0;padding:12px 32px;border-bottom:1px solid var(--ds-line,var(--slate-200))}
.disc-results-h{display:flex;align-items:baseline;justify-content:space-between;gap:12px;margin:18px 0 10px}
.disc-results-h h3{margin:0;font-size:18px;font-weight:600;color:var(--slate-900)}
.pl-stage{appearance:none;border:1px solid transparent;border-radius:16px;padding:6px 28px 6px 12px;font-size:12px;font-weight:600;line-height:1.2;background-color:var(--slate-100);color:var(--slate-900);cursor:pointer;white-space:nowrap}
.pl-stage-pill{display:inline-block;border-radius:16px;padding:4px 10px;font-size:12px;font-weight:600;line-height:1.2;background:var(--slate-100);color:var(--slate-900);white-space:nowrap}
.pl-stage--new{background:var(--slate-100);color:var(--slate-900)}
.pl-stage--creators-added{background:var(--blue-50);color:var(--blue-700)}
.pl-stage--approval{background:var(--amber-100);color:var(--amber-900)}
.pl-stage--approved{background:var(--green-100);color:var(--green-800)}
.pl-stage--rejected{background:var(--red-100);color:var(--red-800)}
.pl-cmt{max-width:260px;min-width:200px}
.pl-clamp{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;text-overflow:ellipsis;line-height:1.45;font-size:13px;color:var(--slate-900)}
.pl-table .ds-sticky-r{min-width:250px}
.pl-actions{display:flex;align-items:center;gap:6px;justify-content:flex-end;white-space:nowrap}
.pl-tools .ds-filter{white-space:nowrap}
.pl-table{min-width:1220px}
.pl-table td:nth-child(2){min-width:170px;max-width:220px;white-space:normal}
.pl-table .pl-cmt{background:inherit}

.pl-stage-wrap{position:relative;display:inline-block}
.pl-stage-wrap .pl-chev{position:absolute;right:10px;top:50%;transform:translateY(-50%);pointer-events:none;opacity:.7}
.pl-stage:hover{border-color:var(--blue-200)}
.pl-stage:focus-visible{outline:2px solid var(--blue-300);outline-offset:2px}
.pl-note{border:1px solid transparent;border-radius:8px;padding:6px 8px;margin:-6px -8px;cursor:text;min-height:34px;transition:background .15s,border-color .15s,box-shadow .15s}
.pl-note:hover,.pl-note:focus-visible{background:#fff;border-color:var(--blue-200);box-shadow:var(--shadow-xs);outline:none}
.pl-note-empty{color:var(--slate-400);font-size:13px}
.pl-note-in{width:100%;min-width:220px;padding:6px 8px;border:1px solid var(--blue-400);border-radius:8px;font-size:13px;background:#fff;box-shadow:var(--shadow-xs)}
.pl-note-in:focus{outline:none}
.pl-tools .ds-filter{white-space:nowrap}
.pl-strip{display:flex;align-items:center;gap:14px;flex-wrap:wrap;background:#fff;border:1px solid var(--slate-200);border-radius:12px;padding:10px 14px;margin:14px 0}
.pl-strip-tags{display:flex;gap:6px;flex-wrap:wrap;flex:1;min-width:200px}
.pl-strip-stats{display:flex;gap:16px;flex-wrap:wrap;font-size:13px;color:var(--slate-500)}
.pl-strip-stats span{display:flex;gap:6px;align-items:baseline}
.pl-strip-stats b{color:var(--slate-900);font-weight:600}
.pl-bulk{display:flex;align-items:center;gap:6px;flex-wrap:wrap;background:var(--slate-800);color:#fff;border-radius:12px;padding:10px 12px 10px 16px;margin:0 0 12px}
.pl-bulk>strong{font-size:14px;font-weight:600;margin-right:6px}
.pl-bulk-sp{flex:1}
.pl-bulk-btn{display:inline-flex;align-items:center;gap:6px;background:transparent;color:#fff;border:0;border-radius:8px;padding:8px 10px;font-family:inherit;font-size:13px;font-weight:500;line-height:1;cursor:pointer}
.pl-bulk-btn:hover{background:color-mix(in srgb, #fff 12%, transparent)}
.pl-bulk-btn.is-danger{color:var(--red-200)}
.pl-bulk-clear{opacity:.75}
.pl-cmp-note{display:flex;gap:10px;align-items:center;margin:0 0 12px;font-size:13px;color:var(--slate-900)}
.pl-rep-head{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin:4px 0 12px}
.pl-rep-head h3{margin:0 0 2px;font-size:16px;font-weight:600}
.pl-rep-head p{margin:0}
.pl-hero{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px;margin-bottom:12px}
.pl-hero-i{background:#fff;border:1px solid var(--slate-200);border-radius:12px;padding:12px 14px;min-width:0}
.pl-hero-i span{display:block;font-size:12px;color:var(--slate-500);text-transform:uppercase;letter-spacing:.05em}
.pl-hero-i b{display:block;font-size:18px;font-weight:600;margin:4px 0 2px;color:var(--slate-900);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.pl-hero-i small{font-size:12px;color:var(--slate-500)}
.pl-rep-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.pl-rep-sec{background:#fff;border:1px solid var(--slate-200);border-radius:12px;padding:12px 14px}
.pl-rep-sec h4{margin:0 0 8px;font-size:13px;font-weight:600;color:var(--slate-900)}
.pl-rv-grid{display:grid;grid-template-columns:140px 1fr;gap:8px 14px;margin:0}
.pl-rv{display:contents}
.pl-rv dt{font-size:13px;color:var(--slate-500)}
.pl-rv dd{margin:0;font-size:13px;color:var(--slate-900);line-height:1.5}
.pl-rv-chip{display:inline-block;background:var(--slate-100);border-radius:16px;padding:2px 10px;margin:0 4px 4px 0;font-size:12px}
.pl-rv-none{color:var(--slate-400);font-size:13px}
@media(max-width:900px){.pl-hero{grid-template-columns:repeat(2,minmax(0,1fr))}.pl-rep-grid{grid-template-columns:1fr}}
.nl-points{margin:10px 0 0;padding-left:18px;font-size:13px;color:var(--slate-900);line-height:1.8}
.nl-input{width:100%;margin-top:6px;padding:10px 12px;border:1px solid var(--slate-300);border-radius:8px;font-size:14px;box-sizing:border-box}
.nl-input:focus{outline:2px solid var(--blue-200);border-color:var(--blue-400)}
.vg{padding:16px 18px;margin-bottom:14px}
.vg-head{display:flex;align-items:baseline;gap:10px;flex-wrap:wrap;margin-bottom:6px}
.vg-svg{display:block;width:100%;height:auto;overflow:visible}
.vg-grid{stroke:var(--slate-100);stroke-width:1}
.vg-tick{font-size:12px;fill:var(--slate-500)}
.vg-end{font-size:12px;font-weight:600;fill:var(--slate-900)}
.vg-line{stroke:var(--blue-700);stroke-width:2.2;stroke-linejoin:round}
.vg-area{fill:var(--blue-700);opacity:.12}
.vg-dot{fill:var(--blue-700)}
.cp-two{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,1fr);gap:14px;align-items:start}
@media (max-width:900px){.cp-two{grid-template-columns:1fr}}
.sv{padding:16px 18px}
.sv-total{display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;margin:6px 0 8px}
.sv-total b{font-size:24px;color:var(--slate-900)}
.sv-total span{font-size:13px;color:var(--slate-500)}
.sv-bar{margin-bottom:10px}
.sv-rows{display:flex;flex-direction:column;max-height:300px;overflow:auto}
.sv-row{display:grid;grid-template-columns:minmax(0,1fr) auto 90px;gap:12px;align-items:center;padding:8px 0;border-top:1px solid var(--slate-100);font-size:13px}
.sv-who{display:flex;flex-direction:column;min-width:0;color:var(--slate-900)}
.sv-who small{color:var(--slate-500);font-size:12px}
.sv-amt{font-variant-numeric:tabular-nums;font-weight:600;color:var(--slate-900)}
.sv-share{height:6px;border-radius:16px;background:var(--blue-50);overflow:hidden}
.sv-share i{display:block;height:100%;background:var(--amber-500);border-radius:16px}
.cr-cost{display:inline-flex;align-items:center;gap:2px}
.cr-cost input{width:104px;text-align:right;padding:6px 8px;border:1px solid var(--blue-200);border-radius:8px;background:#fff}
.cr-cost input:focus{outline:2px solid var(--blue-800);outline-offset:1px}
.cr-rupee{color:var(--slate-500)}
.cr-owner{min-width:118px}
.cr-wrap{overflow-x:auto}
.cr-table{min-width:1180px}
.cr-table td:last-child,.cr-table th:last-child{position:static}
.ds-avatar,.ds-avatar--sm,.ds-avatar-stack .ds-avatar,.ds-avatar.ds-spoc,.cq-av{width:24px !important;height:24px !important;min-width:24px;border-radius:50%;color:#fff;font-size:12px;font-weight:600;letter-spacing:0 !important;border:0;box-shadow:none;margin:0 !important;box-sizing:border-box !important}
.ds-avatar-stack .ds-avatar{margin-left:-4px !important;border:1px solid #fff}
.ds-avatar-stack .ds-avatar:first-child{margin-left:0 !important}
.ds-avatar-more{width:24px;height:24px;border-radius:50%;background:var(--slate-100);color:var(--slate-500);font-size:12px;border:1px solid var(--slate-200)}
.tv{margin:0 0 16px;padding:18px;border:1px solid var(--slate-200);border-radius:12px;background:#fff}
.tv-head{display:flex;justify-content:space-between;align-items:flex-start;gap:14px;flex-wrap:wrap;margin-bottom:14px}
.tv-title{font-size:14px;font-weight:600;color:var(--slate-900)}
.tv-sub{margin:4px 0 0;font-size:13px;color:var(--slate-500)}
.tv-ctrl{display:flex;align-items:center;gap:6px}
.tv-select{display:inline-flex}
select.tv-select{border:1px solid var(--blue-200);border-radius:8px;padding:8px 12px;font-size:13px;font-weight:600;color:var(--slate-900);background:#fff;cursor:pointer}
.tv-nav{width:32px;height:32px;border:1px solid var(--blue-200);border-radius:8px;background:#fff;color:var(--slate-900);font-size:16px;cursor:pointer}
.tv-kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));border:1px solid var(--slate-100);border-radius:8px;margin-bottom:14px}
.tv-kpis>div{padding:12px 14px;display:flex;flex-direction:column;gap:2px;border-right:1px solid var(--slate-100);min-width:0}
.tv-kpis>div:last-child{border-right:0}
.tv-kpis>div>span{font-size:12px;color:var(--slate-500)}
.tv-kpis b{font-size:20px;color:var(--slate-900);font-variant-numeric:tabular-nums}
.tv-kpis small{font-size:12px;color:var(--slate-500)}
.tv-split{display:flex;height:6px;border-radius:16px;overflow:hidden;background:var(--blue-50);margin-top:6px}
.tv-split i{display:block;height:100%}
.tv-org{background:var(--blue-800)}
.tv-boo{background:var(--amber-500)}
.tv-chart{position:relative}
.tv-svg{display:block;width:100%;height:auto;overflow:visible}
.tv-area-org{fill:var(--blue-800);opacity:.88}
.tv-area-boo{fill:var(--amber-500);opacity:.88}
.tv-dot-pt{fill:#fff;stroke:var(--blue-800);stroke-width:2}
.tv-hit{fill:transparent;cursor:crosshair}
.tv-hit.is-on{fill:color-mix(in srgb, var(--blue-800) 7%, transparent)}
.tv-tip{position:absolute;top:0;width:180px;background:var(--slate-900);color:#fff;border-radius:8px;padding:10px 12px;font-size:12px;display:flex;flex-direction:column;gap:4px;box-shadow:var(--shadow-lg);pointer-events:none;z-index:2}
.tv-tip[hidden]{display:none}
.tv-tip b{font-size:13px}
.tv-tip-split{display:flex;align-items:center;gap:6px}
.tv-tip-split i{width:8px;height:8px;border-radius:4px;display:inline-block}
.tv-legend{display:flex;gap:14px;font-size:12px;color:var(--slate-600);margin:10px 0 0;flex-wrap:wrap}
.tv-legend span{display:inline-flex;align-items:center;gap:6px}
.tv-legend i{width:10px;height:10px;border-radius:4px;display:inline-block}
.tv-legend .tv-dot{background:#fff;border:2px solid var(--blue-800);border-radius:50%;width:9px;height:9px}
.tv-chips{display:flex;gap:6px;overflow-x:auto;padding:12px 0 2px;margin-top:10px;border-top:1px solid var(--slate-100)}
.tv-chip{flex:none;border:1px solid var(--slate-200);background:#fff;border-radius:16px;padding:6px 12px;font-size:12px;color:var(--slate-900);cursor:pointer;white-space:nowrap}
